import{_ as t,o as r,c as n,Q as o}from"./chunks/framework.48927342.js";const j=JSON.parse('{"title":"Module 3: 当事情不如我们所愿时","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/modules/maltese-module3-analysis.md","filePath":"zh/more/maltese/modules/maltese-module3-analysis.md"}'),a={name:"zh/more/maltese/modules/maltese-module3-analysis.md"},s=o('<h1 id="module-3-当事情不如我们所愿时" tabindex="-1">Module 3: 当事情不如我们所愿时 <a class="header-anchor" href="#module-3-当事情不如我们所愿时" aria-label="Permalink to &quot;Module 3: 当事情不如我们所愿时&quot;">​</a></h1><p><strong>模块标题：Meta l-affarijiet ma jmorrux kif nixtiequ</strong><br><strong>英文标题：When things go wrong</strong><br><strong>中文译意：当事情不如我们所愿时</strong></p><h2 id="模块标题解析" tabindex="-1">模块标题解析 <a class="header-anchor" href="#模块标题解析" aria-label="Permalink to &quot;模块标题解析&quot;">​</a></h2><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Meta l-affarijiet ma jmorrux kif nixtiequ</td><td>当事情不如我们所愿时</td><td><strong>Meta</strong> 当……时<br><strong>l-affarijiet</strong> 事情、事物（冠词 l- + affarijiet）<br><strong>ma jmorrux</strong> 它们不按某种方式发展、不顺利（ma … -x 构成否定；肯定形式为 jmorru，字面是“它们走”）<br><strong>kif</strong> 如同、按照……的方式<br><strong>nixtiequ</strong> 我们希望、我们想要（第一人称复数）。</td></tr></tbody></table><p>英文标题 <strong>When things go wrong</strong> 可译为“当事情出岔子时”；马耳他语标题更贴近“当事情不如我们所愿时”。本模块通过遗失物品、迟到、事故及服务投诉等情景练习遇到问题时的表达。</p><h2 id="整体大纲" tabindex="-1">整体大纲 <a class="header-anchor" href="#整体大纲" aria-label="Permalink to &quot;整体大纲&quot;">​</a></h2><table><thead><tr><th>页码</th><th>内容</th></tr></thead><tbody><tr><td>1–2</td><td>两段日常对话：寻找遗失戒指、迟到求助；阅读理解题</td></tr><tr><td>3–5</td><td>口语情景表达、餐馆投诉评论、书面投诉信</td></tr><tr><td>6–11</td><td>名词单数与复数；复数构词类型；识别句中复数名词</td></tr><tr><td>12–15</td><td>方位介词；根据图片描述物体位置并练习名词复数</td></tr></tbody></table><h3 id="阅读提示" tabindex="-1">阅读提示 <a class="header-anchor" href="#阅读提示" aria-label="Permalink to &quot;阅读提示&quot;">​</a></h3><ul><li><strong>il-/l-</strong> 定冠词，类似英语 <em>the</em>；结合语境可译为“这/那”或不译。</li><li><strong>fil-</strong> 在……里（介词与冠词连写）。</li><li><strong>tal-</strong> ……的（介词与冠词连写）。</li><li><strong>bil-</strong> 用/带……（介词与冠词连写）。</li><li><strong>plural sħiħ</strong> 规则/完整复数，常见加词尾。</li><li><strong>plural miksur</strong> 破碎复数，词干内部也发生变化，不能只靠一个统一规则推出。</li></ul><h2 id="_1-两段对话" tabindex="-1">1 两段对话 <a class="header-anchor" href="#_1-两段对话" aria-label="Permalink to &quot;1 两段对话&quot;">​</a></h2><h3 id="对话一-brenda-找不到戒指" tabindex="-1">对话一：Brenda 找不到戒指 <a class="header-anchor" href="#对话一-brenda-找不到戒指" aria-label="Permalink to &quot;对话一：Brenda 找不到戒指&quot;">​</a></h3><p><strong>Qari — Aqra dawn id-djalogi.</strong>（阅读——读一读这些对话。）</p><ul><li><strong>qari</strong> 阅读。</li><li><strong>aqra</strong> 读（命令式）。</li><li><strong>dawn</strong> 这些。</li><li><strong>id-djalogi</strong> 对话（复数）。</li></ul><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Xi ġralek, Brenda?</td><td>Brenda，你怎么了？</td><td><strong>xi</strong> 什么<br><strong>ġralek</strong> 发生在你身上/你出了什么事（ġara + le-k）<br><strong>Brenda</strong> 人名。</td></tr><tr><td>Ħaw’, Anna, tlift iċ-ċurkett!</td><td>嗨，Anna，我把戒指弄丢了！</td><td><strong>Ħaw’</strong> 嗨<br><strong>tlift</strong> 我丢了<br><strong>iċ-ċurkett</strong> 这枚戒指（冠词 + 戒指）。</td></tr><tr><td>Fejn kont l-aħħar?</td><td>你最后一次（记得）是在哪里？</td><td><strong>fejn</strong> 哪里<br><strong>kont</strong> 你曾经在/你当时在<br><strong>l-aħħar</strong> 最后、上一次。</td></tr><tr><td>Ilni ġurnata ndur il-ħwienet!</td><td>我逛商店已经逛了一整天！</td><td><strong>ilni</strong> 我已经……这么久<br><strong>ġurnata</strong> 一天<br><strong>ndur</strong> 我四处转/逛<br><strong>il-ħwienet</strong> 这些商店（复数）。</td></tr><tr><td>Ma nafx meta kien l-aħħar f’subgħi!</td><td>我不知道它最后一次在我手指上是什么时候！</td><td><strong>ma … x</strong> 否定框架<br><strong>nafx</strong> 我不知道<br><strong>meta</strong> 什么时候<br><strong>kien</strong> 是/在（过去）<br><strong>l-aħħar</strong> 最后一次<br><strong>f’</strong> 在……上/里<br><strong>subgħi</strong> 我的手指。</td></tr><tr><td>Ikkalma. Prova aħseb ftit.</td><td>冷静点，试着想一想。</td><td><strong>ikkalma</strong> 冷静下来（命令式）<br><strong>prova</strong> 试试<br><strong>aħseb</strong> 想<br><strong>ftit</strong> 一点儿。</td></tr><tr><td>Iva! Sakemm xtrajt il-libsa kien għadu f’subgħajja għax jien u nippruvaha weħilli magħha.</td><td>对！我买那条裙子时它还在我手指上，因为我试穿时它勾在裙子上了。</td><td><strong>iva</strong> 对<br><strong>sakemm</strong> 到……时/当……时<br><strong>xtrajt</strong> 我买了<br><strong>il-libsa</strong> 这条裙子<br><strong>kien għadu</strong> 仍然是/还在<br><strong>f’</strong> 在<br><strong>subgħajja</strong> 我的手指上<br><strong>għax</strong> 因为<br><strong>jien u nippruvaha</strong> 我在试穿它的时候<br><strong>weħilli</strong> 它粘住/挂住了我<br><strong>magħha</strong> 在它上面/和它一起（指裙子）。</td></tr><tr><td>Mela ejja mmorru f’dak il-ħanut, forsi waqagħlek hemm.</td><td>那我们去那家店吧，也许它在那里掉了。</td><td><strong>mela</strong> 那么<br><strong>ejja</strong> 来吧<br><strong>mmorru</strong> 我们去<br><strong>f’dak</strong> 在那一个<br><strong>il-ħanut</strong> 商店<br><strong>forsi</strong> 也许<br><strong>waqagħlek</strong> 它从你身上掉了<br><strong>hemm</strong> 那里。</td></tr><tr><td>Nispera li jekk sabu xi ħadd, ma baqax sejjer bih!</td><td>我希望如果有人捡到了，他没有把它带走！</td><td><strong>nispera</strong> 我希望<br><strong>li</strong> ……<br><strong>jekk</strong> 如果<br><strong>sabu</strong> 他找到了它（sab + 宾语后缀 -u；主语是后面的 xi ħadd，不是“他们”）<br><strong>xi ħadd</strong> 某个人<br><strong>ma … x</strong> 否定<br><strong>baqax</strong> 没有继续<br><strong>sejjer</strong> 走<br><strong>bih</strong> 带着它。</td></tr></tbody></table><h3 id="对话二-emily-错过公交车" tabindex="-1">对话二：Emily 错过公交车 <a class="header-anchor" href="#对话二-emily-错过公交车" aria-label="Permalink to &quot;对话二：Emily 错过公交车&quot;">​</a></h3><p>关于迟到和等下一班车的句子已按你校正后的转录稿补全。</p><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Ħelow, is-Sur Caruana?</td><td>喂，请问是 Caruana 先生吗？</td><td><strong>Ħelow</strong> 喂/您好<br><strong>is-Sur</strong> 先生<br><strong>Caruana</strong> 姓氏。</td></tr><tr><td>Iva, jien hu, għidli.</td><td>是我，请说。</td><td><strong>iva</strong> 是<br><strong>jien</strong> 我<br><strong>hu</strong> 他/就是本人（此处指接电话的人）<br><strong>għidli</strong> 告诉我/请说。</td></tr><tr><td>Sur Caruana, jien Emily. Skużani imma ħa nasal tard għax-xogħol għax tlift tal-linja bl-eżatt!</td><td>Caruana 先生，我是 Emily。对不起，我上班要迟到了，因为我刚好错过了公交车！</td><td><strong>Sur Caruana</strong> Caruana 先生<br><strong>jien</strong> 我（这里省略“是”）<br><strong>Emily</strong> 人名<br><strong>Skużani</strong> 请原谅我、对不起<br><strong>imma</strong> 但是<br><strong>ħa nasal</strong> 我将会到达（ħa 表将来，nasal 表“我到达”）<br><strong>tard</strong> 晚、迟<br><strong>għax-xogħol</strong> 去上班、到工作地点（għal + 冠词 + xogħol 的连写形式；这里不是“因为”）<br><strong>għax</strong> 因为<br><strong>tlift</strong> 我错过了<br><strong>tal-linja</strong> 公交车（此处省略 karozza，完整表达为 karozza tal-linja）<br><strong>bl-eżatt</strong> 正好、恰恰。</td></tr><tr><td>Issa fadal nofs siegħa oħra sabiex tgħaddi oħra.</td><td>现在还要再等半小时，才会有另一班公交车经过。</td><td><strong>Issa</strong> 现在<br><strong>fadal</strong> 还剩、还需要（时间）<br><strong>nofs siegħa</strong> 半小时（nofs：一半；siegħa：小时）<br><strong>oħra</strong> 再一个、另外的（修饰 siegħa；nofs siegħa oħra 合起来指“再半小时”）<br><strong>sabiex</strong> 为了、以便；此处结合等车语境译为“才会……”<br><strong>tgħaddi</strong> 它经过（第三人称阴性单数，指公交车）<br><strong>oħra</strong> 另一辆、另一班（阴性单数，省略了指公交车的名词）。</td></tr><tr><td>Żgur ma tistax tagħmel mod ieħor? Forsi jista’ jwasslek xi ħadd?</td><td>你肯定不能想别的办法吗？也许有人能送你？</td><td><strong>żgur</strong> 肯定<br><strong>ma tistax</strong> 你不能<br><strong>tagħmel</strong> 做<br><strong>mod ieħor</strong> 另一种办法<br><strong>forsi</strong> 也许<br><strong>jista’</strong> 能<br><strong>jwasslek</strong> 把你送到<br><strong>xi ħadd</strong> 某个人。</td></tr><tr><td>Ħadd ma jista’ jwassalni bħalissa għax il-papà għandu l-karozza bil-ħsara.</td><td>现在没人能送我，因为爸爸的车坏了。</td><td><strong>ħadd</strong> 没有人<br><strong>ma jista’</strong> 不能<br><strong>jwassalni</strong> 把我送到<br><strong>bħalissa</strong> 现在、此刻<br><strong>għax</strong> 因为<br><strong>il-papà</strong> 爸爸<br><strong>għandu</strong> 他有<br><strong>il-karozza</strong> 汽车<br><strong>bil-ħsara</strong> 有损坏/坏了。</td></tr><tr><td>Jekk naqbad taxi tiġini ftit għolja.</td><td>如果我打车，会贵一点。</td><td><strong>jekk</strong> 如果<br><strong>naqbad</strong> 我乘/我搭<br><strong>taxi</strong> 出租车<br><strong>tiġini</strong> 对我来说会变得/会花<br><strong>ftit</strong> 有点<br><strong>għolja</strong> 贵（字面“高”）。</td></tr><tr><td>Inti fejn qiegħda?</td><td>你在哪里？（对女性说）</td><td><strong>inti</strong> 你<br><strong>fejn</strong> 哪里<br><strong>qiegħda</strong> 位于/待着（阴性形式）。</td></tr><tr><td>Ħa nara jekk il-ħaddiema humiex qrib tiegħek bil-vann tax-xogħol. Fil-każ jgħaddu għalik huma.</td><td>我看看工人们是否在你附近、开着工作用的货车；如果可以，他们会顺路来接你。</td><td><strong>ħa nara</strong> 我来看看<br><strong>jekk</strong> 是否<br><strong>il-ħaddiema</strong> 工人们<br><strong>humiex</strong> 是否是/是否在<br><strong>qrib</strong> 附近<br><strong>tiegħek</strong> 你的<br><strong>bil-vann</strong> 开着/乘坐货车<br><strong>tax-xogħol</strong> 工作用的<br><strong>fil-każ</strong> 如果是这样<br><strong>jgħaddu</strong> 他们经过/顺路<br><strong>għalik</strong> 为你<br><strong>huma</strong> 他们。</td></tr><tr><td>Jien qiegħda ż-Żurrieq, fil-pjazza.</td><td>我在 Żurrieq 的广场。</td><td><strong>jien</strong> 我<br><strong>qiegħda</strong> 位于（女性说话者）<br><strong>ż-Żurrieq</strong> 地名 Żurrieq<br><strong>fil-pjazza</strong> 在广场上。</td></tr><tr><td>Ok, se niċċekkja u nerġa’ nċempillek.</td><td>好，我查一下再给你回电话。</td><td><strong>se</strong> 将要<br><strong>niċċekkja</strong> 我检查<br><strong>u</strong> 和<br><strong>nerġa’</strong> 我再/重新<br><strong>nċempillek</strong> 我打电话给你。</td></tr><tr><td>Illaħwa, kieku tajjeb! Grazzi, Sur Caruana, u skużani mill-ġdid.</td><td>哎呀，那就太好了！谢谢你，Caruana 先生，再次向你道歉。</td><td><strong>illaħwa</strong> 哎呀/天哪（感叹）<br><strong>kieku</strong> 那样的话<br><strong>tajjeb</strong> 好<br><strong>grazzi</strong> 谢谢<br><strong>u</strong> 和<br><strong>skużani</strong> 原谅我<br><strong>mill-ġdid</strong> 再一次。</td></tr></tbody></table><hr><h2 id="_2-对话理解题" tabindex="-1">2 对话理解题 <a class="header-anchor" href="#_2-对话理解题" aria-label="Permalink to &quot;2 对话理解题&quot;">​</a></h2><p><strong>Wieġeb dawn il-mistoqsijiet dwar l-ewwel djalogu.</strong>（回答关于第一段对话的问题。）</p><table><thead><tr><th>题目</th><th>中文与逐词拆解</th></tr></thead><tbody><tr><td>Min huma l-karattri ta’ dan id-djalogu?</td><td>这段对话里有哪些人物？<br><strong>min</strong> 谁<br><strong>huma</strong> 是<br><strong>il-karattri</strong> 人物<br><strong>ta’ dan</strong> 这个……的<br><strong>id-djalogu</strong> 对话。<br>参考答案：Brenda 和 Anna。</td></tr><tr><td>X’inhi l-problema?</td><td>问题是什么？<br><strong>x’inhi</strong> 是什么（阴性）<br><strong>il-problema</strong> 问题。<br>参考答案：Brenda 丢了戒指。</td></tr><tr><td>Brenda fejn qed taħseb li tilfitu ċ-ċurkett?</td><td>Brenda 觉得自己可能在哪里弄丢戒指？<br><strong>fejn</strong> 哪里<br><strong>qed taħseb</strong> 正在想/认为<br><strong>li</strong> ……<br><strong>tilfitu</strong> 把它丢了<br><strong>iċ-ċurkett</strong> 戒指。<br>参考答案：可能在她买裙子的商店。</td></tr><tr><td>X’qed tispera Brenda?</td><td>Brenda 正在希望什么？<br><strong>x’</strong> 什么<br><strong>qed</strong> 正在<br><strong>tispera</strong> 她希望。<br>参考答案：希望捡到戒指的人没有把它带走。</td></tr></tbody></table><p><strong>Wieġeb dawn il-mistoqsijiet dwar it-tieni djalogu.</strong>（回答关于第二段对话的问题。）</p><table><thead><tr><th>题目</th><th>中文与逐词拆解</th></tr></thead><tbody><tr><td>Min huma l-karattri ta’ dan id-djalogu?</td><td>这段对话里有哪些人物？参考答案：Emily 和 Caruana 先生。</td></tr><tr><td>X’inhi l-problema?</td><td>问题是什么？参考答案：Emily 错过公交车，快迟到了；爸爸的车又坏了。</td></tr><tr><td>Lil min ċemplet Emily?</td><td>Emily 给谁打了电话？<br><strong>lil min</strong> 给谁<br><strong>ċemplet</strong> 她打电话了。<br>参考答案：Caruana 先生。</td></tr><tr><td>Fejn qed tistenna Emily?</td><td>Emily 在哪里等？<br><strong>fejn</strong> 哪里<br><strong>qed tistenna</strong> 正在等待<br><strong>Emily</strong> 人名。<br>参考答案：Żurrieq 的广场。</td></tr></tbody></table><h3 id="八题马耳他语完整参考答案" tabindex="-1">八题马耳他语完整参考答案 <a class="header-anchor" href="#八题马耳他语完整参考答案" aria-label="Permalink to &quot;八题马耳他语完整参考答案&quot;">​</a></h3><table><thead><tr><th>题号</th><th>参考答案与逐词解析</th></tr></thead><tbody><tr><td>1</td><td><strong>Il-karattri huma Brenda u Anna.</strong> 人物是 Brenda 和 Anna。<br><strong>il-karattri</strong> 人物<br><strong>huma</strong> 是<br><strong>Brenda</strong> 人名<br><strong>u</strong> 和<br><strong>Anna</strong> 人名。</td></tr><tr><td>2</td><td><strong>Brenda tilfet iċ-ċurkett.</strong> Brenda 弄丢了戒指。<br><strong>Brenda</strong> 人名<br><strong>tilfet</strong> 她丢失了<br><strong>iċ-ċurkett</strong> 戒指。</td></tr><tr><td>3</td><td><strong>Brenda taħseb li tilfet iċ-ċurkett fil-ħanut fejn xtrat il-libsa.</strong> Brenda 认为戒指丢在买裙子的商店。<br><strong>Brenda</strong> 人名<br><strong>taħseb</strong> 她认为<br><strong>li</strong> 引导从句<br><strong>tilfet</strong> 她丢了<br><strong>iċ-ċurkett</strong> 戒指<br><strong>fil-ħanut</strong> 在商店里<br><strong>fejn</strong> ……的地方<br><strong>xtrat</strong> 她买了<br><strong>il-libsa</strong> 裙子。</td></tr><tr><td>4</td><td><strong>Brenda tispera li min sab iċ-ċurkett ma ħadux miegħu.</strong> Brenda 希望捡到戒指的人没有把它带走。<br><strong>Brenda</strong> 人名<br><strong>tispera</strong> 她希望<br><strong>li</strong> 引导从句<br><strong>min</strong> ……的人<br><strong>sab</strong> 他找到了<br><strong>iċ-ċurkett</strong> 戒指<br><strong>ma ħadux</strong> 他没有拿走它（否定与宾语后缀）<br><strong>miegħu</strong> 随他、跟着他。</td></tr><tr><td>5</td><td><strong>Il-karattri huma Emily u s-Sur Caruana.</strong> 人物是 Emily 和 Caruana 先生。<br><strong>il-karattri</strong> 人物<br><strong>huma</strong> 是<br><strong>Emily</strong> 人名<br><strong>u</strong> 和<br><strong>s-Sur Caruana</strong> Caruana 先生。</td></tr><tr><td>6</td><td><strong>Emily tilfet tal-linja u se tasal tard għax-xogħol.</strong> Emily 错过公交车，将迟到。<br><strong>Emily</strong> 人名<br><strong>tilfet</strong> 她错过了<br><strong>tal-linja</strong> 公交车（省略 karozza）<br><strong>u</strong> 和<br><strong>se</strong> 将要<br><strong>tasal</strong> 她到达<br><strong>tard</strong> 迟<br><strong>għax-xogħol</strong> 去上班。</td></tr><tr><td>7</td><td><strong>Emily ċemplet lis-Sur Caruana.</strong> Emily 给 Caruana 先生打电话。<br><strong>Emily</strong> 人名<br><strong>ċemplet</strong> 她打了电话<br><strong>lis-Sur Caruana</strong> 给 Caruana 先生。</td></tr><tr><td>8</td><td><strong>Emily qed tistenna fil-pjazza taż-Żurrieq.</strong> Emily 在 Żurrieq 的广场等候。<br><strong>Emily</strong> 人名<br><strong>qed</strong> 正在<br><strong>tistenna</strong> 她等待<br><strong>fil-pjazza</strong> 在广场上<br><strong>taż-Żurrieq</strong> Żurrieq 的。</td></tr></tbody></table><p>两组读题共用词语：</p><ul><li><strong>wieġeb</strong> 回答。</li><li><strong>dawn il-mistoqsijiet</strong> 这些问题。</li><li><strong>dwar</strong> 关于。</li><li><strong>l-ewwel djalogu</strong> 第一段对话。</li><li><strong>it-tieni djalogu</strong> 第二段对话。</li></ul><hr><h2 id="_3-看图口语表达" tabindex="-1">3 看图口语表达 <a class="header-anchor" href="#_3-看图口语表达" aria-label="Permalink to &quot;3 看图口语表达&quot;">​</a></h2><p><strong>It-Taħdit — X’ġara f’dawn l-istampi?</strong>（口语——这些图片里发生了什么？）</p><h3 id="交通事故-碰撞" tabindex="-1">交通事故/碰撞 <a class="header-anchor" href="#交通事故-碰撞" aria-label="Permalink to &quot;交通事故/碰撞&quot;">​</a></h3><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Skużani ħafna!</td><td>非常抱歉！</td><td><strong>skużani</strong> 请原谅我<br><strong>ħafna</strong> 很、非常。</td></tr><tr><td>Ma rajtekx… ma ndunajtx bik… kont aljenat/a.</td><td>我没看见你……没注意到你……我刚才走神了。</td><td><strong>ma … x</strong> 没有<br><strong>rajtek</strong> 我看见你<br><strong>ndunajtx</strong> 我没注意到<br><strong>bik</strong> 你<br><strong>kont</strong> 我当时<br><strong>aljenat/a</strong> 分心的（阳/阴性）。</td></tr><tr><td>Tort tiegħek! Suppost inti waqaft!</td><td>是你的错！你本来应该停下来的！</td><td><strong>tort</strong> 过错<br><strong>tiegħek</strong> 你的<br><strong>suppost</strong> 本来应该<br><strong>inti</strong> 你<br><strong>waqaft</strong> 你停下了。</td></tr><tr><td>Għandek raġun, mhux apposta!</td><td>你说得对，不是故意的！</td><td><strong>għandek raġun</strong> 你有道理<br><strong>mhux</strong> 不<br><strong>apposta</strong> 故意。</td></tr><tr><td>X’qatgħa ħadt!</td><td>我吓了一大跳！</td><td><strong>x’qatgħa</strong> 多大的惊吓<br><strong>ħadt</strong> 我受到了（此词形也可表示“你受到了”，须按说话情景区分）。</td></tr><tr><td>Weġġajt?</td><td>你受伤了吗？</td><td><strong>weġġajt</strong> 你受伤了。</td></tr><tr><td>Ħa nċempel għall-ambulanza.</td><td>我来打电话叫救护车。</td><td><strong>ħa</strong> 将要/我来<br><strong>nċempel</strong> 我打电话<br><strong>għall-</strong> 给/为了<br><strong>ambulanza</strong> 救护车。</td></tr><tr><td>Ħa nċempel għall-warden.</td><td>我来打电话叫道路交通管理员/警员。</td><td><strong>ħa nċempel</strong> 我来打电话<br><strong>għall-warden</strong> 给 warden（原文借词，指现场管理/执勤人员）。</td></tr><tr><td>Xi ħadd jista’ jgħinna?</td><td>有人能帮我们吗？</td><td><strong>xi ħadd</strong> 某个人/有人<br><strong>jista’</strong> 能<br><strong>jgħinna</strong> 帮助我们。</td></tr><tr><td>Tiċċaqlaqx!</td><td>别动！</td><td><strong>tiċċaqlaq</strong> 移动<br><strong>-x</strong> 否定命令。</td></tr></tbody></table><h3 id="在商店里询问商品" tabindex="-1">在商店里询问商品 <a class="header-anchor" href="#在商店里询问商品" aria-label="Permalink to &quot;在商店里询问商品&quot;">​</a></h3><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Fejn hu…?</td><td>……在哪里？</td><td><strong>fejn</strong> 哪里<br><strong>hu</strong> 它在哪里（阳性名词）。</td></tr><tr><td>Qed infittex … ma nistax insibu.</td><td>我正在找……，但我找不到它。</td><td><strong>qed infittex</strong> 正在寻找<br><strong>ma nistax</strong> 我不能/无法<br><strong>insibu</strong> 找到它。</td></tr><tr><td>Taf fejn nista’ nsib…?</td><td>你知道我可以在哪里找到……吗？</td><td><strong>taf</strong> 你知道<br><strong>fejn</strong> 哪里<br><strong>nista’</strong> 我可以<br><strong>nsib</strong> 找到。</td></tr><tr><td>Għandkom / Għandek…?</td><td>你们有/你有……吗？</td><td><strong>għandkom</strong> 你们有<br><strong>għandek</strong> 你有。</td></tr><tr><td>Liema naħa qiegħed il-laħam?</td><td>肉在什么方向/哪一边？</td><td><strong>liema</strong> 哪一个<br><strong>naħa</strong> 一边/方向<br><strong>qiegħed</strong> 位于<br><strong>il-laħam</strong> 肉。</td></tr><tr><td>Kemm hu dan il-prodott? Kemm jiswa?</td><td>这个产品多少钱？它值多少钱？</td><td><strong>kemm</strong> 多少<br><strong>hu</strong> 是<br><strong>dan</strong> 这个<br><strong>il-prodott</strong> 产品<br><strong>jiswa</strong> 价格为/值。</td></tr><tr><td>Hawn xi offerti?</td><td>这里有优惠吗？</td><td><strong>hawn</strong> 这里有<br><strong>xi</strong> 一些/任何<br><strong>offerti</strong> 优惠、特价。</td></tr></tbody></table><h3 id="在餐馆投诉" tabindex="-1">在餐馆投诉 <a class="header-anchor" href="#在餐馆投诉" aria-label="Permalink to &quot;在餐馆投诉&quot;">​</a></h3><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Wejter! Dan l-ikel mhux tajjeb!</td><td>服务员！这食物不好吃/不合格！</td><td><strong>wejter</strong> 服务员<br><strong>dan</strong> 这<br><strong>l-ikel</strong> 食物<br><strong>mhux tajjeb</strong> 不好。</td></tr><tr><td>Dan l-ikel kiesaħ!</td><td>这食物是凉的！</td><td><strong>dan</strong> 这<br><strong>l-ikel</strong> 食物<br><strong>kiesaħ</strong> 冷的。</td></tr><tr><td>Dan il-laħam misjur ħafna u iebes.</td><td>这肉煮得太老，而且很硬。</td><td><strong>dan</strong> 这<br><strong>il-laħam</strong> 肉<br><strong>misjur</strong> 熟透/煮老<br><strong>ħafna</strong> 很、过于<br><strong>u</strong> 和<br><strong>iebes</strong> 硬。</td></tr><tr><td>Din it-tiġieġa għadha roża, bid-demm.</td><td>这只鸡还发粉，里面有血。</td><td><strong>din</strong> 这（阴性）<br><strong>it-tiġieġa</strong> 鸡肉/鸡<br><strong>għadha</strong> 仍然<br><strong>roża</strong> 粉红<br><strong>bid-demm</strong> 带着血。</td></tr><tr><td>Jien mhux dan il-platt ordnajt.</td><td>我点的不是这道菜。</td><td><strong>jien</strong> 我<br><strong>mhux</strong> 不是<br><strong>dan il-platt</strong> 这盘菜<br><strong>ordnajt</strong> 我点了。</td></tr><tr><td>Dan l-ikel mielaħ ħafna.</td><td>这食物太咸了。</td><td><strong>mielaħ</strong> 咸<br><strong>ħafna</strong> 很、太。</td></tr><tr><td>Dan żgur ma fihx dqiq / ħalib?</td><td>这个肯定不含面粉/牛奶吧？</td><td><strong>dan</strong> 这个<br><strong>żgur</strong> 肯定<br><strong>ma fihx</strong> 不含<br><strong>dqiq</strong> 面粉<br><strong>ħalib</strong> 牛奶。</td></tr><tr><td>Nixtieq inkellem lill-maniġer jekk ma jimpurtax.</td><td>如果方便的话，我想和经理谈谈。</td><td><strong>nixtieq</strong> 我想<br><strong>inkellem</strong> 我谈话/联系<br><strong>lill-maniġer</strong> 那位经理<br><strong>jekk</strong> 如果<br><strong>ma jimpurtax</strong> 不介意/没关系。</td></tr></tbody></table><hr><h2 id="_4-情景对话与餐馆评论" tabindex="-1">4 情景对话与餐馆评论 <a class="header-anchor" href="#_4-情景对话与餐馆评论" aria-label="Permalink to &quot;4 情景对话与餐馆评论&quot;">​</a></h2><p><strong>Agħżel xenarju minn dawn it-tlieta u pprepara djalogu li ser tippreżenta quddiem sħabek.</strong></p><p>从三个情景中选一个，准备一段要在同学面前表演的对话。</p><ul><li><strong>agħżel</strong> 选择</li><li><strong>xenarju</strong> 情景</li><li><strong>minn</strong> 从</li><li><strong>dawn it-tlieta</strong> 这三个</li><li><strong>u</strong> 并</li><li><strong>pprepara</strong> 准备</li><li><strong>djalogu</strong> 对话</li><li><strong>li ser</strong> 将要……的</li><li><strong>tippreżenta</strong> 你展示</li><li><strong>quddiem</strong> 在……面前</li><li><strong>sħabek</strong> 你的同伴/同学。</li></ul><h3 id="情景对话参考答案-餐馆" tabindex="-1">情景对话参考答案（餐馆） <a class="header-anchor" href="#情景对话参考答案-餐馆" aria-label="Permalink to &quot;情景对话参考答案（餐馆）&quot;">​</a></h3><table><thead><tr><th>补写句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Klijent: Skużani, dan l-ikel kiesaħ.</td><td>顾客：对不起，这食物是冷的。<br><strong>klijent</strong> 顾客<br><strong>skużani</strong> 对不起<br><strong>dan</strong> 这<br><strong>l-ikel</strong> 食物<br><strong>kiesaħ</strong> 冷的。</td></tr><tr><td>Wejter: Jiddispjaċini. Trid platt ieħor?</td><td>服务员：抱歉。您要换一盘吗？<br><strong>wejter</strong> 服务员<br><strong>jiddispjaċini</strong> 我很抱歉<br><strong>trid</strong> 你想要<br><strong>platt</strong> 一盘菜<br><strong>ieħor</strong> 另一个。</td></tr><tr><td>Klijent: Iva, jekk jogħġbok.</td><td>顾客：好的，麻烦您。<br><strong>iva</strong> 是的<br><strong>jekk jogħġbok</strong> 请、麻烦您。</td></tr><tr><td>Wejter: Se nġiblek platt sħun minnufih.</td><td>服务员：我马上给您拿一盘热的。<br><strong>se</strong> 将要<br><strong>nġiblek</strong> 我拿来给你<br><strong>platt</strong> 一盘<br><strong>sħun</strong> 热的<br><strong>minnufih</strong> 立刻。</td></tr></tbody></table><p><strong>Il-Qari — Aqra dan l-ilment u l-kummenti daqslikieku rajthom fuq il-midja soċjali.</strong></p><p>阅读这则投诉和评论，假装你是在社交媒体上看到它们。</p><ul><li><strong>aqra</strong> 读</li><li><strong>dan l-ilment</strong> 这则投诉</li><li><strong>u</strong> 和</li><li><strong>il-kummenti</strong> 评论</li><li><strong>daqslikieku</strong> 仿佛</li><li><strong>rajthom</strong> 你看到了它们</li><li><strong>fuq</strong> 在……上</li><li><strong>il-midja soċjali</strong> 社交媒体。</li></ul><h3 id="rachel-的评论" tabindex="-1">Rachel 的评论 <a class="header-anchor" href="#rachel-的评论" aria-label="Permalink to &quot;Rachel 的评论&quot;">​</a></h3><blockquote><p><strong>Ma nirrakkomandax ir-ristorant “Bella Malta” li jinsab Marsaxlokk minħabba s-servizz ħażin li rċivejna!</strong></p><p>我不推荐位于 Marsaxlokk 的 “Bella Malta” 餐厅，因为我们得到的服务很差！</p><ul><li><strong>ma nirrakkomandax</strong> 我不推荐</li><li><strong>ir-ristorant</strong> 餐厅</li><li><strong>li</strong> ……的</li><li><strong>jinsab</strong> 位于</li><li><strong>minħabba</strong> 因为</li><li><strong>is-servizz</strong> 服务</li><li><strong>ħażin</strong> 差</li><li><strong>rċivejna</strong> 我们收到/得到。</li></ul></blockquote><blockquote><p><strong>Meta poġġejna domna nistennew nofs siegħa sakemm ġie l-wejter jagħtina l-menus, u dam tliet kwarti oħra biex jieħu l-ordni.</strong></p><p>我们坐下后等了半小时，服务员才来给我们菜单；之后他又花了四十五分钟才来点单。</p><ul><li><strong>meta</strong> 当</li><li><strong>poġġejna</strong> 我们坐下</li><li><strong>domna</strong> 我们花了（时间）</li><li><strong>nistennew</strong> 等待</li><li><strong>nofs siegħa</strong> 半小时</li><li><strong>sakemm</strong> 直到</li><li><strong>ġie</strong> 他来了</li><li><strong>il-wejter</strong> 服务员</li><li><strong>jagħtina</strong> 给我们</li><li><strong>il-menus</strong> 菜单（复数）</li><li><strong>u</strong> 并且</li><li><strong>dam</strong> 他花了</li><li><strong>tliet kwarti oħra</strong> 又三个一刻钟/四十五分钟</li><li><strong>biex</strong> 才/为了</li><li><strong>jieħu</strong> 他拿/取</li><li><strong>l-ordni</strong> 订单。</li></ul></blockquote><blockquote><p><strong>Agħar minn hekk, meta l-ordni waslet kienet ħażina u minfuq ried ir-raġun il-wejter!</strong></p><p>更糟的是，订单送来时还弄错了，而且服务员竟然还坚持自己有理！</p><ul><li><strong>agħar</strong> 更糟</li><li><strong>minn hekk</strong> 比这</li><li><strong>meta</strong> 当</li><li><strong>waslet</strong> 它到达（阴性，指订单）</li><li><strong>kienet ħażina</strong> 是错的</li><li><strong>u</strong> 而且</li><li><strong>minfuq</strong> 更有甚者/此外</li><li><strong>ried</strong> 他想要/坚持</li><li><strong>ir-raġun</strong> 正确、道理</li><li><strong>il-wejter</strong> 服务员。</li></ul></blockquote><h3 id="两条回复" tabindex="-1">两条回复 <a class="header-anchor" href="#两条回复" aria-label="Permalink to &quot;两条回复&quot;">​</a></h3><table><thead><tr><th>原文</th><th>中文与逐词拆解</th></tr></thead><tbody><tr><td>Mario: Ma naqbilx miegħek, meta morna hemm dejjem ħriġna sodisfatti. Kellimtu lill-maniġer? Kont tirranġa xi ħaġa żgur!</td><td>Mario：我不同意你；我们去那里时每次都满意地离开。你跟经理谈了吗？肯定能解决点什么！<br><strong>ma naqbilx</strong> 我不同意<br><strong>miegħek</strong> 和你<br><strong>meta morna</strong> 当我们去了<br><strong>hemm</strong> 那里<br><strong>dejjem</strong> 总是<br><strong>ħriġna</strong> 我们离开<br><strong>sodisfatti</strong> 满意<br><strong>kellimtu</strong> 你和他谈过吗<br><strong>lill-maniġer</strong> 和经理<br><strong>kont tirranġa</strong> 你本来可以解决<br><strong>xi ħaġa</strong> 某件事<br><strong>żgur</strong> 肯定。</td></tr><tr><td>Ritianne: Kieku jien kont inqum u nitlaq meta nara li l-wejter għadu ma ġabx il-menus!</td><td>Ritianne：如果是我，看到服务员还没拿来菜单，我就会起身离开！<br><strong>kieku jien</strong> 如果是我<br><strong>kont</strong> 我会/我当时会<br><strong>inqum</strong> 起身<br><strong>u</strong> 并<br><strong>nitlaq</strong> 离开<br><strong>meta</strong> 当<br><strong>nara</strong> 我看见<br><strong>li</strong> ……<br><strong>għadu</strong> 仍然<br><strong>ma ġabx</strong> 没拿来<br><strong>il-menus</strong> 菜单。</td></tr></tbody></table><hr><h2 id="_5-书面投诉" tabindex="-1">5 书面投诉 <a class="header-anchor" href="#_5-书面投诉" aria-label="Permalink to &quot;5 书面投诉&quot;">​</a></h2><p><strong>Il-kitba ta’ lment</strong> = 投诉写作。</p><ul><li><strong>kitba</strong> 写作</li><li><strong>ta’</strong> ……的</li><li><strong>ilment</strong> 投诉。</li></ul><h3 id="a-填空投诉范文" tabindex="-1">A. 填空投诉范文 <a class="header-anchor" href="#a-填空投诉范文" aria-label="Permalink to &quot;A. 填空投诉范文&quot;">​</a></h3><p>题目词库：</p><ul><li><strong>nistenna</strong> 我等待</li><li><strong>iddiżappuntata</strong> 失望的，阴性</li><li><strong>nirrapporta</strong> 我报告/投诉</li><li><strong>teknixin</strong> 技术员</li><li><strong>friġġ</strong> 冰箱。</li></ul><table><thead><tr><th>句子（补全后）</th><th>中文与词语拆解</th></tr></thead><tbody><tr><td>Ninsab iddiżappuntata bil-prodotti li xtrajt mingħand “Lino tal-Appliances”.</td><td>我对从 “Lino tal-Appliances” 买来的产品很失望。<br><strong>ninsab</strong> 我处于/我感到<br><strong>iddiżappuntata</strong> 失望（女性说话者）<br><strong>bil-prodotti</strong> 对这些产品<br><strong>li</strong> ……的<br><strong>xtrajt</strong> 我买了<br><strong>mingħand</strong> 从……那里。</td></tr><tr><td>Wara biss xahrejn, il-friġġ bdiet tissaddad u l-magna tal-ħasil mhix taħdem sew.</td><td>才过两个月，冰箱就开始生锈，洗衣机也无法正常工作。<br><strong>wara</strong> 之后<br><strong>biss</strong> 仅仅<br><strong>xahrejn</strong> 两个月<br><strong>il-friġġ</strong> 冰箱<br><strong>bdiet</strong> 开始（阴性形式）<br><strong>tissaddad</strong> 生锈<br><strong>u</strong> 和<br><strong>il-magna tal-ħasil</strong> 洗衣机<br><strong>mhix taħdem sew</strong> 不正常工作。<br>原文语法主谓性别似有不一致，照材料表达理解。</td></tr><tr><td>Meta ċempilt biex nirrapporta, qaluli li rrid nistenna xahar biex jiġi t-teknixin.</td><td>我打电话投诉时，他们告诉我还得等一个月，技术员才会来。<br><strong>meta</strong> 当<br><strong>ċempilt</strong> 我打电话<br><strong>biex</strong> 为了<br><strong>nirrapporta</strong> 我投诉<br><strong>qaluli</strong> 他们告诉我<br><strong>li</strong> ……<br><strong>rrid</strong> 我必须<br><strong>nistenna</strong> 等<br><strong>xahar</strong> 一个月<br><strong>biex jiġi</strong> 以便他来<br><strong>it-teknixin</strong> 技术员。</td></tr><tr><td>Jien ma nistax nagħmel xahar bla magna tal-ħasil!</td><td>我不能一个月都没有洗衣机用！<br><strong>jien</strong> 我<br><strong>ma nistax</strong> 我不能<br><strong>nagħmel</strong> 度过/做<br><strong>xahar</strong> 一个月<br><strong>bla</strong> 没有<br><strong>magna tal-ħasil</strong> 洗衣机。</td></tr></tbody></table><h3 id="b-投诉信句子框架" tabindex="-1">B. 投诉信句子框架 <a class="header-anchor" href="#b-投诉信句子框架" aria-label="Permalink to &quot;B. 投诉信句子框架&quot;">​</a></h3><p><strong>Kompli dawn is-sentenzi biex tagħqad din l-ittra ta’ lment.</strong>（续写这些句子，完成这封投诉信。）</p><table><thead><tr><th>马耳他语</th><th>中文</th><th>逐词拆解</th></tr></thead><tbody><tr><td>Sur Cachia,</td><td>Cachia 先生：</td><td><strong>Sur</strong> 先生<br><strong>Cachia</strong> 姓氏。</td></tr><tr><td>Ilbieraħ użajt is-servizz tal-kumpanija tiegħek “Ħassiela tad-djar”.</td><td>昨天我使用了贵公司“家庭清洁服务”。</td><td><strong>ilbieraħ</strong> 昨天<br><strong>użajt</strong> 我使用了<br><strong>is-servizz</strong> 服务<br><strong>tal-kumpanija</strong> 公司的<br><strong>tiegħek</strong> 你的/贵方<br><strong>Ħassiela tad-djar</strong> 家庭清洁公司名。</td></tr><tr><td>Jiddispjaċini ngħidlek dan għaliex …</td><td>很遗憾要告诉您这件事，因为……</td><td><strong>jiddispjaċini</strong> 我很抱歉<br><strong>ngħidlek</strong> 告诉您<br><strong>dan</strong> 这件事<br><strong>għaliex</strong> 因为。</td></tr><tr><td>Nixtieq li …</td><td>我希望……</td><td><strong>nixtieq</strong> 我希望/想要<br><strong>li</strong> ……（引出从句）。</td></tr><tr><td>Nispera li taċċetta.</td><td>希望您能接受。</td><td><strong>nispera</strong> 我希望<br><strong>li</strong> ……<br><strong>taċċetta</strong> 您接受。</td></tr><tr><td>Saħħiet, Is-Sinjura Fenech</td><td>此致，Fenech 女士</td><td><strong>saħħiet</strong> 祝好/再见<br><strong>is-Sinjura</strong> 女士<br><strong>Fenech</strong> 姓氏。</td></tr></tbody></table><h3 id="b-完整续写参考答案" tabindex="-1">B. 完整续写参考答案 <a class="header-anchor" href="#b-完整续写参考答案" aria-label="Permalink to &quot;B. 完整续写参考答案&quot;">​</a></h3><blockquote><p>Sur Cachia,</p><p>Ilbieraħ użajt is-servizz tal-kumpanija tiegħek “Ħassiela tad-djar”. Jiddispjaċini ngħidlek li ma kontx sodisfatta, dan għaliex l-art baqgħet maħmuġa u t-twieqi ma tnaddfux sew.</p><p>Nixtieq li tibgħat lil xi ħadd biex jerġa’ jnaddaf id-dar.</p><p>Nispera li taċċetta l-ilment tiegħi u li ssolvi din il-problema.</p><p>Saħħiet,</p><p>Is-Sinjura Fenech</p></blockquote><p>新增部分逐句解析：</p><table><thead><tr><th>补写部分</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>li ma kontx sodisfatta</td><td>我并不满意。<br><strong>li</strong> 引导从句<br><strong>ma kontx</strong> 我不是／我没有处于<br><strong>sodisfatta</strong> 满意的（女性）。</td></tr><tr><td>l-art baqgħet maħmuġa u t-twieqi ma tnaddfux sew</td><td>地板仍很脏，窗户也没擦干净。<br><strong>l-art</strong> 地板<br><strong>baqgħet</strong> 仍然、保持（阴性）<br><strong>maħmuġa</strong> 脏的<br><strong>u</strong> 并且<br><strong>t-twieqi</strong> 窗户<br><strong>ma tnaddfux</strong> 没有被清洁<br><strong>sew</strong> 好好地。</td></tr><tr><td>tibgħat lil xi ħadd biex jerġa’ jnaddaf id-dar</td><td>您派人重新打扫房子。<br><strong>tibgħat</strong> 你派遣<br><strong>lil xi ħadd</strong> 某个人（宾语）<br><strong>biex</strong> 为了<br><strong>jerġa’</strong> 他再次<br><strong>jnaddaf</strong> 打扫<br><strong>id-dar</strong> 房子。</td></tr><tr><td>l-ilment tiegħi u li ssolvi din il-problema</td><td>我的投诉，并解决这个问题。<br><strong>l-ilment</strong> 投诉<br><strong>tiegħi</strong> 我的<br><strong>u</strong> 并且<br><strong>li</strong> 引导从句<br><strong>ssolvi</strong> 你解决<br><strong>din</strong> 这个（阴性）<br><strong>il-problema</strong> 问题。</td></tr></tbody></table><h3 id="c-自由写作" tabindex="-1">C. 自由写作 <a class="header-anchor" href="#c-自由写作" aria-label="Permalink to &quot;C. 自由写作&quot;">​</a></h3><p><strong>Agħżel servizz jew prodott u ikteb ilment dwaru.</strong> 选择一项服务或产品，写一封关于它的投诉。</p><ul><li><strong>agħżel</strong> 选择</li><li><strong>servizz</strong> 服务</li><li><strong>jew</strong> 或</li><li><strong>prodott</strong> 产品</li><li><strong>u</strong> 并</li><li><strong>ikteb</strong> 写</li><li><strong>ilment</strong> 投诉</li><li><strong>dwaru</strong> 关于它。</li></ul><h3 id="c-投诉范文及逐句解析" tabindex="-1">C. 投诉范文及逐句解析 <a class="header-anchor" href="#c-投诉范文及逐句解析" aria-label="Permalink to &quot;C. 投诉范文及逐句解析&quot;">​</a></h3><blockquote><p>Għażiż Maniġer,</p><p>Ilbieraħ xtrajt mowbajl mill-ħanut tiegħek. Meta wasalt id-dar, indunajt li l-iskrin ma kienx jaħdem. Nixtieq mowbajl ieħor jew il-flus lura. Nispera li ssolvi din il-problema malajr.</p><p>Grazzi, Alex</p></blockquote><table><thead><tr><th>句子</th><th>中文与逐词解析</th></tr></thead><tbody><tr><td>Għażiż Maniġer</td><td>尊敬的经理。<br><strong>għażiż</strong> 亲爱的／尊敬的<br><strong>maniġer</strong> 经理。</td></tr><tr><td>Ilbieraħ xtrajt mowbajl mill-ħanut tiegħek.</td><td>昨天我从贵店买了一部手机。<br><strong>ilbieraħ</strong> 昨天<br><strong>xtrajt</strong> 我买了<br><strong>mowbajl</strong> 手机<br><strong>mill-ħanut</strong> 从商店<br><strong>tiegħek</strong> 你的。</td></tr><tr><td>Meta wasalt id-dar, indunajt li l-iskrin ma kienx jaħdem.</td><td>回家后，我发现屏幕不能工作。<br><strong>meta</strong> 当……时<br><strong>wasalt</strong> 我到达<br><strong>id-dar</strong> 家<br><strong>indunajt</strong> 我注意到<br><strong>li</strong> 引导从句<br><strong>l-iskrin</strong> 屏幕<br><strong>ma kienx</strong> 当时不<br><strong>jaħdem</strong> 工作、运行。</td></tr><tr><td>Nixtieq mowbajl ieħor jew il-flus lura.</td><td>我希望换一部手机或退款。<br><strong>nixtieq</strong> 我想要<br><strong>mowbajl</strong> 手机<br><strong>ieħor</strong> 另一个<br><strong>jew</strong> 或者<br><strong>il-flus</strong> 钱<br><strong>lura</strong> 回来。</td></tr><tr><td>Nispera li ssolvi din il-problema malajr.</td><td>希望您尽快解决这个问题。<br><strong>nispera</strong> 我希望<br><strong>li</strong> 引导从句<br><strong>ssolvi</strong> 你解决<br><strong>din il-problema</strong> 这个问题<br><strong>malajr</strong> 尽快。</td></tr><tr><td>Grazzi, Alex</td><td>谢谢，Alex。<br><strong>grazzi</strong> 谢谢<br><strong>Alex</strong> 署名。</td></tr></tbody></table><hr><h2 id="_6-单数与复数词表" tabindex="-1">6 单数与复数词表 <a class="header-anchor" href="#_6-单数与复数词表" aria-label="Permalink to &quot;6 单数与复数词表&quot;">​</a></h2><p><strong>Is-Singular u l-Plural. Kompli din it-tabella.</strong>（单数与复数；完成表格。）词条和常用对应如下；空格处按本册其他页中的复数形式补全：</p><table><thead><tr><th>单数</th><th>复数</th><th>中文</th></tr></thead><tbody><tr><td>xogħol</td><td>xogħlijiet</td><td>工作、工作项目</td></tr><tr><td>siegħa</td><td>sigħat</td><td>小时</td></tr><tr><td>karozza</td><td>karozzi</td><td>汽车</td></tr><tr><td>ħaddiem</td><td>ħaddiema</td><td>工人</td></tr><tr><td>vann</td><td>vannijiet</td><td>厢式货车</td></tr><tr><td>servizz</td><td>servizzi</td><td>服务</td></tr><tr><td>restorant</td><td>restorants</td><td>餐馆</td></tr><tr><td>wejter</td><td>wejters</td><td>服务员</td></tr><tr><td>maniġer</td><td>maniġers</td><td>经理</td></tr><tr><td>menu</td><td>menus</td><td>菜单</td></tr><tr><td>ċurkett</td><td>ċrieket</td><td>戒指</td></tr><tr><td>ħanut</td><td>ħwienet</td><td>商店</td></tr><tr><td>suba’</td><td>swaba’</td><td>手指（所有格等词形中出现 subgħ-）</td></tr><tr><td>libsa</td><td>ilbiesi</td><td>连衣裙</td></tr><tr><td>pjazza</td><td>pjazez</td><td>广场</td></tr><tr><td>xahar</td><td>xhur</td><td>月份</td></tr></tbody></table><p><strong>词语提示：</strong></p><ul><li><em>singular</em> = 单数</li><li><em>plural</em> = 复数</li><li><em>kompli</em> = 继续/补全</li><li><em>din it-tabella</em> = 这张表。</li></ul><hr><h2 id="_7-规则-完整复数" tabindex="-1">7 规则/完整复数 <a class="header-anchor" href="#_7-规则-完整复数" aria-label="Permalink to &quot;7 规则/完整复数&quot;">​</a></h2><p><strong>Plural Sħiħ — Żieda ta’ suffiss mal-kelma. Adding a suffix to the word.</strong></p><p>“完整复数”常通过在词干上加词尾形成。此页按原表抄列，箭头左侧为单数、右侧为复数；有些词还伴随拼写或词干变化，宜整组记忆。</p><table><thead><tr><th>单数 → 复数</th><th>中文</th></tr></thead><tbody><tr><td>Malti → Maltin</td><td>马耳他人（男性/泛指）</td></tr><tr><td>Għawdxi → Għawdxin</td><td>戈佐岛人</td></tr><tr><td>Baħri → baħrin</td><td>水手</td></tr><tr><td>Barri → barrin</td><td>公牛</td></tr><tr><td>Qaddis → qaddisin</td><td>圣人、圣徒</td></tr><tr><td>Ħalliel → ħallelin</td><td>小偷</td></tr><tr><td>Għażżien → għażżenin</td><td>懒惰的人</td></tr><tr><td>Għajjien → għajjenin</td><td>疲倦的人</td></tr><tr><td>Għatu → għotjien</td><td>盖子</td></tr><tr><td>Qiegħ → qigħan</td><td>底部</td></tr><tr><td>Triq → triqat</td><td>道路（按教材拼写）</td></tr><tr><td>Xemgħa → xemgħat</td><td>蜡烛</td></tr><tr><td>Tebgħa → tebgħat</td><td>污渍</td></tr><tr><td>Demgħa → demgħat</td><td>眼泪</td></tr><tr><td>Ġimgħa → ġimgħat</td><td>星期/周</td></tr><tr><td>Wied → widien</td><td>山谷</td></tr><tr><td>Bieb → bibien</td><td>门</td></tr><tr><td>Sid → sidien</td><td>主人、所有者</td></tr><tr><td>Għar → għerien</td><td>洞穴</td></tr><tr><td>Dnub → dnubiet</td><td>罪、过错</td></tr><tr><td>Tfajla → tfajliet</td><td>女孩</td></tr><tr><td>Omm → ommijiet</td><td>母亲</td></tr><tr><td>Missier → missirijiet</td><td>父亲</td></tr><tr><td>Vann → vannijiet</td><td>厢式货车</td></tr><tr><td>Xogħol → xogħlijiet</td><td>工作、工作项目</td></tr><tr><td>Ħaddiem → ħaddiema</td><td>工人</td></tr><tr><td>Għalliem → għalliema</td><td>教师</td></tr><tr><td>Sajjied → sajjieda</td><td>渔民</td></tr><tr><td>Karozza → karozzi</td><td>汽车</td></tr><tr><td>Ferrovija → ferroviji</td><td>火车</td></tr><tr><td>Ajruplan → ajruplani</td><td>飞机</td></tr><tr><td>Biljett → biljetti</td><td>票</td></tr><tr><td>Mowbajl → mowbajls</td><td>手机</td></tr><tr><td>Kompjuter → kompjuters</td><td>电脑</td></tr><tr><td>Wejter → wejters</td><td>服务员</td></tr><tr><td>Restorant → restorants</td><td>餐馆</td></tr></tbody></table><p><strong>逐词读题：</strong></p><ul><li><em>Żieda</em> 增加</li><li><em>ta’</em> ……的</li><li><em>suffiss</em> 后缀</li><li><em>mal-kelma</em> 加在词上。</li></ul><p>例：<strong>karozza</strong>（汽车）→ <strong>karozzi</strong>（汽车，复数）。</p><hr><h2 id="_8-看图写复数-一" tabindex="-1">8 看图写复数（一） <a class="header-anchor" href="#_8-看图写复数-一" aria-label="Permalink to &quot;8 看图写复数（一）&quot;">​</a></h2><p><strong>Imla l-vojt billi tagħti l-kelma skont l-istampa u fil-ġenb ikteb jekk hux plural sħiħ jew miksur.</strong></p><p>根据图片填词，并在旁边写出它是完整复数还是破碎复数。</p><ul><li><strong>imla l-vojt</strong> 填空</li><li><strong>billi</strong> 通过</li><li><strong>tagħti</strong> 给出</li><li><strong>il-kelma</strong> 词</li><li><strong>skont</strong> 根据</li><li><strong>l-istampa</strong> 图片</li><li><strong>fil-ġenb</strong> 在旁边</li><li><strong>ikteb</strong> 写</li><li><strong>jekk hux</strong> 是否是</li><li><strong>sħiħ</strong> 完整</li><li><strong>jew</strong> 或</li><li><strong>miksur</strong> 破碎。</li></ul><table><thead><tr><th>图片</th><th>单数 → 复数</th><th>类型</th></tr></thead><tbody><tr><td>一个球 → 多个球</td><td>ballun → blalen</td><td>破碎复数：元音/词干内部变化。教材已给出此例。</td></tr><tr><td>一个纽扣 → 多个纽扣</td><td>buttuna → buttuni</td><td>完整复数（常见规则词尾形式）。</td></tr><tr><td>一张桌子 → 多张桌子</td><td>mejda → imwejjed</td><td>破碎复数。</td></tr><tr><td>一个杯子 → 多个杯子</td><td>tazza → tazzi</td><td>完整复数。</td></tr><tr><td>一只袜子 → 多只袜子</td><td>kalzetta → kalzetti</td><td>完整复数。</td></tr></tbody></table><hr><h2 id="_9-看图写复数-二" tabindex="-1">9 看图写复数（二） <a class="header-anchor" href="#_9-看图写复数-二" aria-label="Permalink to &quot;9 看图写复数（二）&quot;">​</a></h2><p>本页延续第 8 页的表格与指令，图片依次为摩托车、铅笔、小狗、小猫和水桶。</p><p>逐词：</p><ul><li><strong>singular</strong> 单数</li><li><strong>plural</strong> 复数。</li></ul><table><thead><tr><th>图片</th><th>单数 → 复数</th><th>类型</th></tr></thead><tbody><tr><td>摩托车</td><td>mutur → muturi</td><td>完整复数</td></tr><tr><td>铅笔</td><td>lapes → lapsijiet</td><td>完整复数（-ijiet 词尾）</td></tr><tr><td>小狗</td><td>kelb → klieb</td><td>破碎复数</td></tr><tr><td>小猫</td><td>qattus → qtates</td><td>破碎复数</td></tr><tr><td>水桶</td><td>barmil → bramel</td><td>破碎复数</td></tr></tbody></table><hr><h2 id="_10-看图写复数-三" tabindex="-1">10 看图写复数（三） <a class="header-anchor" href="#_10-看图写复数-三" aria-label="Permalink to &quot;10 看图写复数（三）&quot;">​</a></h2><p>本页图片依次为一个男孩/多个孩子、一部手机/多部手机、一张床/多张床、一把伞/多把伞。</p><table><thead><tr><th>图片</th><th>单数 → 复数</th><th>类型</th></tr></thead><tbody><tr><td>男孩 → 孩子们</td><td>tifel → tfal</td><td>破碎复数</td></tr><tr><td>手机</td><td>mowbajl → mowbajls</td><td>完整复数</td></tr><tr><td>床</td><td>sodda → sodod</td><td>破碎复数</td></tr><tr><td>雨伞</td><td>umbrella → umbrelel</td><td>破碎复数（借词常见复数）</td></tr></tbody></table><hr><h2 id="_11-句子中的复数名词" tabindex="-1">11 句子中的复数名词 <a class="header-anchor" href="#_11-句子中的复数名词" aria-label="Permalink to &quot;11 句子中的复数名词&quot;">​</a></h2><p><strong>It-taħriġ dwar in-nomi u l-għadd.</strong>（关于名词和数的练习。）</p><ul><li><strong>taħriġ</strong> 练习</li><li><strong>dwar</strong> 关于</li><li><strong>in-nomi</strong> 名词</li><li><strong>l-għadd</strong> 数量/数。</li></ul><p>题目要求在复数名词下画线，再写出其单数并标记 <strong>s</strong>（完整复数）或 <strong>m</strong>（破碎复数）。</p><table><thead><tr><th>原句</th><th>中文</th><th>复数名词逐词分析</th></tr></thead><tbody><tr><td>Iż-żeffiena tal-grupp ħarġu tajjeb ħafna imma nistqarr li s-saħħa tal-grupp tinsab fil-kantanti.</td><td>舞团的舞者表现得很好，不过我承认，这个团体的实力在于歌手。</td><td><strong>iż-żeffiena</strong> 舞者（复数，单数 <em>żeffien</em>）<br><strong>il-kantanti</strong> 歌手（复数，单数 <em>kantant</em>）。<br><strong>grupp</strong> 团体<br><strong>saħħa</strong> 力量<br><strong>tajjeb</strong> 好均不是复数名词。</td></tr><tr><td>Il-bajjiet Maltin sbieħ imma l-ibħra tal-madwar sfortunatament ma tantx jinżammu nodfa.</td><td>马耳他的海滩很美，但周围的海域很遗憾并没有保持得很干净。</td><td><strong>il-bajjiet</strong> 海滩（单数 <em>bajja</em>）<br><strong>l-ibħra</strong> 海域/海洋（单数 <em>baħar</em>）。<br><strong>Maltin</strong> 马耳他的、马耳他人，是修饰语<br><strong>sbieħ/nodfa</strong> 美丽/干净是形容词。</td></tr><tr><td>Il-molol tas-sodod ġodda tajbin ħafna.</td><td>新床垫的弹簧很好。</td><td><strong>il-molol</strong> 弹簧（单数 <em>molla</em>）<br><strong>is-sodod</strong> 床（单数 <em>sodda</em>）<br><strong>ġodda</strong> 新的<br><strong>tajbin</strong> 好的为复数形容词。</td></tr><tr><td>Id-djar tagħhom huma kbar. Għandhom ħafna garaxxijiet u kollha kbar.</td><td>他们的房子很大。他们有很多车库，而且全都很大。</td><td><strong>id-djar</strong> 房子（单数 <em>dar</em>）<br><strong>garaxxijiet</strong> 车库（单数 <em>garaxx</em>）。<br><strong>kbar</strong> 大的<br><strong>kollha</strong> 全部为复数形式，但这里要找名词。</td></tr><tr><td>Tassew rajt annimali sbieħ fil-foresti li żort. Imma l-aktar annimali li laqtuni kienu l-iljunfanti.</td><td>我确实在去过的森林里看见了漂亮的动物。但最打动我的是大象。</td><td><strong>annimali</strong> 动物（复数，单数 <em>annimal</em>，出现两次）<br><strong>il-foresti</strong> 森林（单数 <em>foresta</em>）<br><strong>l-iljunfanti</strong> 大象（单数 <em>iljunfant</em>）。<br>按句面共有四处复数名词出现；练习表格只有 11 行，可能与题目排版/计分有关。</td></tr></tbody></table><p><strong>B 题表头：</strong></p><ul><li><em>In-nom il-plural</em> 复数名词</li><li><em>Plural sħiħ / Plural miksur</em> 完整/破碎复数</li><li><em>In-nom fis-singular</em> 单数名词。</li></ul><p>示例：<strong>żeffiena → żeffien</strong>，标 <strong>s</strong>。</p><h3 id="a-原句其余词语的完整解析" tabindex="-1">A. 原句其余词语的完整解析 <a class="header-anchor" href="#a-原句其余词语的完整解析" aria-label="Permalink to &quot;A. 原句其余词语的完整解析&quot;">​</a></h3><table><thead><tr><th>原句编号</th><th>补充逐词／短语解析</th></tr></thead><tbody><tr><td>1</td><td><strong>tal-grupp</strong> 团体的<br><strong>ħarġu</strong> 他们表现出来／他们出来了<br><strong>tajjeb</strong> 好<br><strong>ħafna</strong> 很<br><strong>imma</strong> 但是<br><strong>nistqarr</strong> 我承认<br><strong>li</strong> 引导从句<br><strong>s-saħħa</strong> 实力、力量<br><strong>tal-grupp</strong> 团体的<br><strong>tinsab</strong> 位于、体现在<br><strong>fil-kantanti</strong> 在歌手们身上。</td></tr><tr><td>2</td><td><strong>Maltin</strong> 马耳他的（复数形容词）<br><strong>sbieħ</strong> 美丽的（复数）<br><strong>imma</strong> 但是<br><strong>tal-madwar</strong> 周围的<br><strong>sfortunatament</strong> 不幸地<br><strong>ma tantx</strong> 不太、不怎么<br><strong>jinżammu</strong> 被保持<br><strong>nodfa</strong> 干净的（复数）。</td></tr><tr><td>3</td><td><strong>tas-sodod</strong> 床的<br><strong>ġodda</strong> 新的（复数，可结合语境看修饰床或弹簧）<br><strong>tajbin</strong> 好的（复数）<br><strong>ħafna</strong> 很。<br>译文中“床垫”是情景化理解，原词 sodod 直接指“床”。</td></tr><tr><td>4</td><td><strong>tagħhom</strong> 他们的<br><strong>huma</strong> 是<br><strong>kbar</strong> 大的（复数）<br><strong>għandhom</strong> 他们有<br><strong>ħafna</strong> 很多<br><strong>u</strong> 和<br><strong>kollha</strong> 全部<br><strong>kbar</strong> 大的。</td></tr><tr><td>5</td><td><strong>tassew</strong> 确实<br><strong>rajt</strong> 我看到了<br><strong>sbieħ</strong> 美丽的（复数）<br><strong>fil-foresti</strong> 在森林里<br><strong>li</strong> ……的<br><strong>żort</strong> 我游览过<br><strong>imma</strong> 但是<br><strong>l-aktar</strong> 最……的<br><strong>annimali</strong> 动物<br><strong>li</strong> ……的<br><strong>laqtuni</strong> 它们打动了我<br><strong>kienu</strong> 它们是（过去）<br><strong>l-iljunfanti</strong> 大象。</td></tr></tbody></table><h3 id="b-全部分类与单数答案" tabindex="-1">B. 全部分类与单数答案 <a class="header-anchor" href="#b-全部分类与单数答案" aria-label="Permalink to &quot;B. 全部分类与单数答案&quot;">​</a></h3><p>按不重复词条列出，共 11 个；<code>annimali</code> 在第 5 句出现两次，但这里只录一项。</p><table><thead><tr><th>复数名词</th><th>s / m</th><th>单数</th><th>中文</th></tr></thead><tbody><tr><td>żeffiena</td><td>s</td><td>żeffien</td><td>舞者；教材已给例词</td></tr><tr><td>kantanti</td><td>s</td><td>kantant</td><td>歌手</td></tr><tr><td>bajjiet</td><td>s</td><td>bajja</td><td>海湾／海滩</td></tr><tr><td>ibħra</td><td>m</td><td>baħar</td><td>海洋</td></tr><tr><td>molol</td><td>m</td><td>molla</td><td>弹簧</td></tr><tr><td>sodod</td><td>m</td><td>sodda</td><td>床</td></tr><tr><td>djar</td><td>m</td><td>dar</td><td>房屋</td></tr><tr><td>garaxxijiet</td><td>s</td><td>garaxx</td><td>车库</td></tr><tr><td>annimali</td><td>s</td><td>annimal</td><td>动物</td></tr><tr><td>foresti</td><td>s</td><td>foresta</td><td>森林</td></tr><tr><td>iljunfanti</td><td>s</td><td>iljunfant</td><td>大象</td></tr></tbody></table><ul><li><strong>aqta’ linja taħt</strong> 在……下面画线。</li><li><strong>in-nomi fis-sentenzi</strong> 句子中的名词。</li><li><strong>li qegħdin fil-plural</strong> 处于复数形式的。</li><li><strong>ikteb il-kliem</strong> 写出词语。</li><li><strong>li qtajt linja taħtu</strong> 你在其下方画线的。</li><li><strong>immarka</strong> 标记。</li><li><strong>jekk huwiex</strong> 它是否属于。</li><li><strong>fil-plural sħiħ</strong> 完整复数。</li><li><strong>jew fil-plural miksur</strong> 或破碎复数。</li><li><strong>u ikteb</strong> 并写出。</li><li><strong>is-singular tiegħu</strong> 它的单数形式。</li></ul><hr><h2 id="_12-位置介词-一" tabindex="-1">12 位置介词（一） <a class="header-anchor" href="#_12-位置介词-一" aria-label="Permalink to &quot;12 位置介词（一）&quot;">​</a></h2><p><strong>Il-Prepożizzjonijiet: Fejn qiegħed dan it-tifel?</strong>（介词：这个男孩在哪里？）</p><ul><li><strong>prepożizzjonijiet</strong> 介词</li><li><strong>fejn</strong> 哪里</li><li><strong>qiegħed</strong> 位于</li><li><strong>dan it-tifel</strong> 这个男孩。</li></ul><table><thead><tr><th>介词</th><th>中文</th></tr></thead><tbody><tr><td>taħt</td><td>在……下面</td></tr><tr><td>fuq</td><td>在……上面</td></tr><tr><td>quddiem</td><td>在……前面</td></tr><tr><td>ħdejn / maġenb</td><td>在……旁边</td></tr><tr><td>fuq in-naħa tax-xellug</td><td>在左侧</td></tr><tr><td>fuq in-naħa tal-lemin</td><td>在右侧</td></tr><tr><td>wara</td><td>在……后面</td></tr><tr><td>bejn</td><td>在……之间</td></tr></tbody></table><p>根据图示填空，答案顺序如下（题目按左右两列排列）：</p><ol><li><strong>It-tifel qiegħed quddiem il-kaxxa.</strong> 男孩在箱子前面。<br><strong>it-tifel</strong> 男孩<br><strong>qiegħed</strong> 位于<br><strong>quddiem</strong> 前面<br><strong>il-kaxxa</strong> 箱子。</li><li><strong>It-tifel qiegħed wara l-kaxxa.</strong> 男孩在箱子后面。</li><li><strong>It-tifel jinsab fuq il-kaxxa.</strong> 男孩在箱子上面。<br><strong>jinsab</strong> 位于。</li><li><strong>It-tifel jinsab taħt il-mejda.</strong> 男孩在桌子下面。<br><strong>il-mejda</strong> 桌子。</li><li><strong>It-tifel qiegħed bejn il-kaxxi.</strong> 男孩在两个箱子之间。<br><strong>il-kaxxi</strong> 箱子（复数）。</li><li><strong>It-tifel qiegħed ħdejn il-kaxxa.</strong> 男孩在箱子旁边。</li><li><strong>It-tifel qiegħed fuq in-naħa tax-xellug tal-kaxxa.</strong> 男孩在箱子的左侧。<br><strong>in-naħa</strong> 一侧<br><strong>tax-xellug</strong> 左边的<br><strong>tal-kaxxa</strong> 箱子的。</li><li><strong>It-tifel qiegħed fuq in-naħa tal-lemin tal-kaxxa.</strong> 男孩在箱子的右侧。<br><strong>tal-lemin</strong> 右边的。</li></ol><hr><h2 id="_13-苹果和箱子" tabindex="-1">13 苹果和箱子 <a class="header-anchor" href="#_13-苹果和箱子" aria-label="Permalink to &quot;13 苹果和箱子&quot;">​</a></h2><p><strong>Fejn qiegħda t-tuffieħa?</strong> 苹果在哪里？</p><ul><li><strong>fejn</strong> 哪里</li><li><strong>qiegħda</strong> 位于（阴性）</li><li><strong>it-tuffieħa</strong> 苹果。</li></ul><h3 id="逐图位置说明" tabindex="-1">逐图位置说明 <a class="header-anchor" href="#逐图位置说明" aria-label="Permalink to &quot;逐图位置说明&quot;">​</a></h3><p>共 9 幅小图，按<strong>从上到下、每行从左到右</strong>编号。左右以读图者看到的画面为准；前后主要根据苹果是否遮住箱子、是否被箱子遮住判断。以下为按图理解的参考表达，不是教材提供的答案。</p><table><thead><tr><th>编号与图中位置</th><th>具体描述</th><th>马耳他语参考句</th><th>逐词拆解</th></tr></thead><tbody><tr><td>1：第一行左图</td><td>苹果在箱子上面，放在箱顶。</td><td><strong>It-tuffieħa qiegħda fuq il-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于（阴性单数）<br><strong>fuq</strong> 在……上面（第 12 页）<br><strong>il-kaxxa</strong> 箱子。</td></tr><tr><td>2：第一行中图</td><td>箱子打开，苹果在箱子里面。</td><td><strong>It-tuffieħa qiegħda fil-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>fil-kaxxa</strong> 在箱子里面（fi + il-kaxxa；本页补充表达）。</td></tr><tr><td>3：第一行右图</td><td>苹果在箱子右侧、紧靠箱子旁边。</td><td><strong>It-tuffieħa qiegħda fuq in-naħa tal-lemin tal-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>fuq in-naħa tal-lemin</strong> 在右侧（第 12 页）<br><strong>tal-kaxxa</strong> 箱子的。</td></tr><tr><td>4：第二行左图</td><td>苹果在箱子前面，偏画面左侧，挡住箱子的部分正面。</td><td><strong>It-tuffieħa qiegħda quddiem il-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>quddiem</strong> 在……前面（第 12 页）<br><strong>il-kaxxa</strong> 箱子。</td></tr><tr><td>5：第二行中图</td><td>苹果在箱子后面，偏画面右侧，一部分被箱子遮住。</td><td><strong>It-tuffieħa qiegħda wara l-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>wara</strong> 在……后面（第 12 页）<br><strong>il-kaxxa</strong> 箱子。</td></tr><tr><td>6：第二行右图</td><td>苹果在两个箱子之间。</td><td><strong>It-tuffieħa qiegħda bejn il-kaxxi.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>bejn</strong> 在……之间（第 12 页）<br><strong>il-kaxxi</strong> 箱子（复数，这里指图中的两个箱子）。</td></tr><tr><td>7：第三行左图</td><td>箱子斜放在苹果上方，苹果在箱子下面。</td><td><strong>It-tuffieħa qiegħda taħt il-kaxxa.</strong></td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>taħt</strong> 在……下面（第 12 页）<br><strong>il-kaxxa</strong> 箱子。</td></tr><tr><td>8：第三行中图</td><td>苹果倒置，画在打开的箱子内部区域；暂按“在里面”描述，箱内外关系需核对原图。</td><td><strong>It-tuffieħa qiegħda fil-kaxxa.</strong>（暂定）</td><td><strong>it-tuffieħa</strong> 苹果<br><strong>qiegħda</strong> 位于<br><strong>fil-kaxxa</strong> 在箱子里面（此处读图暂定，不因苹果倒置就判断为“下面”）。</td></tr><tr><td>9：第三行右图</td><td>多个苹果分布在一个箱子周围，不是一个苹果在两个箱子之间。</td><td><strong>It-tuffieħ qiegħed madwar il-kaxxa.</strong></td><td><strong>it-tuffieħ</strong> 苹果（集合名词，指图中的多个苹果）<br><strong>qiegħed</strong> 位于（与集合名词 tuffieħ 搭配）<br><strong>madwar</strong> 在……周围（本页补充表达）<br><strong>il-kaxxa</strong> 箱子。</td></tr></tbody></table><h3 id="与第-12-页词汇的对应" tabindex="-1">与第 12 页词汇的对应 <a class="header-anchor" href="#与第-12-页词汇的对应" aria-label="Permalink to &quot;与第 12 页词汇的对应&quot;">​</a></h3><ul><li><strong>fuq</strong> 上面：对应图 1。</li><li><strong>taħt</strong> 下面：对应图 7。</li><li><strong>quddiem</strong> 前面：对应图 4。</li><li><strong>wara</strong> 后面：对应图 5；与图 3 的区别是苹果被箱子部分遮住。</li><li><strong>bejn</strong> 之间：对应图 6；后面用复数 <strong>il-kaxxi</strong>，因为参照物是两个箱子。</li><li><strong>ħdejn / maġenb</strong> 旁边：图 3 也可说 <strong>It-tuffieħa qiegħda ħdejn il-kaxxa.</strong>，但没有说清左侧还是右侧。</li><li><strong>fuq in-naħa tal-lemin</strong> 右侧：图 3 的更具体表达。这里整个短语表示“在右侧”，不能只看其中的 <strong>fuq</strong> 就译成“上面”。</li><li><strong>fuq in-naħa tax-xellug</strong> 左侧：图 4 从画面看也偏左，可补充说 <strong>It-tuffieħa qiegħda fuq in-naħa tax-xellug tal-kaxxa.</strong>；不过它遮住箱子正面，主要位置关系用 <strong>quddiem</strong> 更贴切。</li><li><strong>fil-kaxxa</strong> 在箱子里面：图 2，以及暂定的图 8；不是“在箱子上面”。</li><li><strong>madwar</strong> 周围：图 9；区别于 <strong>bejn</strong>（在两个或多个参照物之间）。</li></ul><p><strong>仍需核对：</strong> 图 8 的箱体边界和苹果重叠处不够清晰；目前不将“在里面”视为唯一确定答案。图 9 用集合名词 <strong>tuffieħ</strong>，而不是单个苹果的 <strong>tuffieħa</strong>，所以相应改用 <strong>qiegħed</strong>。</p><hr><h2 id="_14-位置介词-二" tabindex="-1">14 位置介词（二） <a class="header-anchor" href="#_14-位置介词-二" aria-label="Permalink to &quot;14 位置介词（二）&quot;">​</a></h2><p><strong>Imla l-vojt billi tuża l-prepożizzjonijiet skont l-istampa.</strong> 根据图片使用介词填空。</p><ul><li><strong>tuża</strong> 使用</li><li><strong>skont l-istampa</strong> 根据图片。</li></ul><table><thead><tr><th>句子</th><th>中文与逐词拆解</th></tr></thead><tbody><tr><td>1. Is-siġġu qiegħed ħdejn il-mejda.</td><td>椅子在桌子旁边。<br><strong>is-siġġu</strong> 椅子<br><strong>qiegħed</strong> 位于<br><strong>ħdejn</strong> 旁边<br><strong>il-mejda</strong> 桌子。<br>此项已给出。</td></tr><tr><td>2. Il-ballun jinsab taħt il-mejda.</td><td>球在桌子下面。<br><strong>il-ballun</strong> 球<br><strong>jinsab</strong> 位于<br><strong>taħt</strong> 下面。</td></tr><tr><td>3. Il-mejda tinsab bejn is-siġġu u l-pultruna.</td><td>桌子在椅子和扶手椅之间。<br><strong>tinsab</strong> 位于（阴性）<br><strong>bejn</strong> 在……之间<br><strong>u</strong> 和<br><strong>il-pultruna</strong> 扶手椅。</td></tr><tr><td>4. Fuq il-pultruna hemm żewġ kuxins.</td><td>扶手椅上有两个靠垫。<br><strong>fuq</strong> 上面<br><strong>il-pultruna</strong> 扶手椅<br><strong>hemm</strong> 有<br><strong>żewġ</strong> 两个<br><strong>kuxins</strong> 靠垫。<br>原题为“____ fil-pultruna hemm...”，本句将 fil-pultruna 改成 il-pultruna，属于自然表达的改写，不是原题原样单词填空。</td></tr><tr><td>5. Il-qattus qiegħed ħdejn il-pultruna.</td><td>猫在扶手椅旁边。<br><strong>il-qattus</strong> 猫<br><strong>qiegħed</strong> 位于<br><strong>ħdejn</strong> 旁边<br><strong>il-pultruna</strong> 扶手椅。<br>图中猫在椅子右侧，选择 ħdejn 更明确；若着眼于局部遮挡也可讨论 wara，但不是唯一可确定的关系。</td></tr><tr><td>6. Il-ktieb qiegħed fuq il-mejda u ħdejn il-lampa.</td><td>书在桌子上、灯旁边。<br><strong>il-ktieb</strong> 书<br><strong>fuq</strong> 上面<br><strong>u</strong> 和<br><strong>ħdejn</strong> 旁边<br><strong>il-lampa</strong> 灯。</td></tr><tr><td>7. Il-vażun qiegħed ħdejn il-lampa.</td><td>花瓶在灯旁边。<br><strong>il-vażun</strong> 花瓶<br><strong>ħdejn</strong> 旁边。</td></tr><tr><td>8. Il-lampa qiegħda bejn il-ktieb u l-vażun.</td><td>灯在书和花瓶之间。<br><strong>il-lampa</strong> 灯<br><strong>qiegħda</strong> 位于（阴性）<br><strong>bejn</strong> 之间。</td></tr><tr><td>9. It-tapit qiegħed quddiem l-affarijiet.</td><td>地毯在这些物品前面。<br><strong>it-tapit</strong> 地毯<br><strong>quddiem</strong> 前面<br><strong>l-affarijiet</strong> 物品（复数）。</td></tr><tr><td>10. L-arloġġ qiegħed fuq l-affarijiet.</td><td>时钟在这些物品上方/上面。<br><strong>l-arloġġ</strong> 时钟<br><strong>fuq</strong> 上面<br><strong>l-affarijiet</strong> 物品。</td></tr></tbody></table><p>第 9、10 题的“物品”参照图中整组家具；具体使用 <em>quddiem</em>（前面）或 <em>fuq</em>（上方）时，重点是按图表达相对位置。</p><hr><h2 id="_15-从图片列单数名词并写复数" tabindex="-1">15 从图片列单数名词并写复数 <a class="header-anchor" href="#_15-从图片列单数名词并写复数" aria-label="Permalink to &quot;15 从图片列单数名词并写复数&quot;">​</a></h2><p><strong>Agħmel lista tan-nomi fis-singular li jidhru fl-istampa, imbagħad agħti l-plural tagħhom u għid hux sħiħ jew miksur.</strong></p><p>把图片中出现的单数名词列出来，再写出复数，并说明是完整复数还是破碎复数。</p><ul><li><strong>agħmel lista</strong> 列清单</li><li><strong>tan-nomi</strong> 名词的</li><li><strong>fis-singular</strong> 单数形式</li><li><strong>li jidhru</strong> 出现/看得见</li><li><strong>fl-istampa</strong> 在图片中</li><li><strong>imbagħad</strong> 然后</li><li><strong>agħti</strong> 给出</li><li><strong>tagħhom</strong> 它们的</li><li><strong>u għid</strong> 并说明</li><li><strong>hux</strong> 是否是</li><li><strong>sħiħ jew miksur</strong> 完整还是破碎。</li></ul><p>本页是空白表格，所指图片应为上一页的客厅插图。可从图中列出以下示例：</p><table><thead><tr><th>单数名词</th><th>复数</th><th>类型</th></tr></thead><tbody><tr><td>siġġu（椅子）</td><td>siġġijiet</td><td>完整</td></tr><tr><td>mejda（桌子）</td><td>mwejjed</td><td>破碎</td></tr><tr><td>ballun（球）</td><td>blalen</td><td>破碎</td></tr><tr><td>pultruna（扶手椅）</td><td>pultruni</td><td>完整</td></tr><tr><td>kuxin（靠垫）</td><td>kuxins</td><td>完整</td></tr><tr><td>qattus（猫）</td><td>qtates</td><td>破碎</td></tr><tr><td>ktieb（书）</td><td>kotba</td><td>破碎</td></tr><tr><td>lampa（灯）</td><td>lampi</td><td>完整</td></tr><tr><td>vażun（花瓶）</td><td>vażuni</td><td>完整</td></tr><tr><td>tapit（地毯）</td><td>twapet</td><td>破碎</td></tr><tr><td>arloġġ（时钟）</td><td>arloġġi</td><td>完整</td></tr></tbody></table><h2 id="复习重点" tabindex="-1">复习重点 <a class="header-anchor" href="#复习重点" aria-label="Permalink to &quot;复习重点&quot;">​</a></h2><ol><li><strong>询问与解释情况：</strong><br><em>X’ġralek?</em>（你怎么了？）<br><em>Ma nafx</em>（我不知道）<br><em>Skużani</em>（对不起/请原谅我）。</li><li><strong>请求帮助与服务：</strong><br><em>Xi ħadd jista’ jgħinni?</em>（有人能帮我吗？）<br><em>Nixtieq inkellem lill-maniġer</em>（我想找经理谈谈）。</li><li><strong>表达位置：</strong><br><em>fuq</em> 上<br><em>taħt</em> 下<br><em>quddiem</em> 前<br><em>wara</em> 后<br><em>bejn</em> 之间<br><em>ħdejn/maġenb</em> 旁边。</li><li><strong>名词复数：</strong> 规则复数和破碎复数都需要结合词例记忆；不要假设所有词都只加同一个后缀。</li></ol>',150),d=[s];function g(i,l,e,b,u,m){return r(),n("div",null,d)}const k=t(a,[["render",g]]);export{j as __pageData,k as default};
